def copy_legacy_attachments(apps, schema_editor):
    Version = apps.get_model('core', 'SubmissionVersion')
    relation = Version.files.through
    batch = []
    for version in Version.objects.exclude(attachment_id=None).iterator(chunk_size=1000):
        batch.append(relation(submissionversion_id=version.id, storedfile_id=version.attachment_id))
        if len(batch) == 1000:
            relation.objects.bulk_create(batch, ignore_conflicts=True)
            batch = []
    relation.objects.bulk_create(batch, ignore_conflicts=True)


